import type { Chapter } from './chapters'
import tinyGptCode from '../examples/tiny-gpt.js?raw'

export const languageChapters: Record<string, Chapter> = {
  tokenization: {
    prerequisites: ['vectors', 'probability'], objectives: ['Trace text into discrete IDs without confusing IDs with meaning.', 'Compare word, character, byte, and subword representations.', 'Account for normalization, special tokens, and sequence length.'],
    sections: [
      { title: 'A model receives tokens, not text directly', paragraphs: ['A tokenizer converts text into a sequence of discrete vocabulary entries. An ID is an index identifying an entry. ID 400 is not more positive, twice as meaningful, or semantically closer to ID 401 than ID 2. Meaning is learned in the embedding vectors looked up by these indices.', 'A tokenizer and model form a contract. The same ID must refer to the same entry during training and inference. Swapping tokenizers without retraining or carefully adapting embeddings breaks that contract, even if both have identical vocabulary size.'] },
      { title: 'The unit determines the trade-off', paragraphs: ['Word tokens make familiar words compact but struggle with rare words, morphology, spelling variations, and enormous vocabularies. Character tokens use a small vocabulary but require longer sequences. Byte-level representations can cover arbitrary encoded text with a small base alphabet.', 'Subword methods balance these extremes: frequent pieces become single tokens and rare words decompose. A token is not necessarily a word, syllable, or Unicode character. Emoji and non-Latin text may require different token counts depending on the tokenizer.'], example: 'The text "unhappiness" might be one word token, eleven character tokens, or pieces such as "un", "happi", "ness". Those exact pieces are vocabulary-dependent; there is no universal segmentation.' },
      { title: 'Normalization changes the information available', paragraphs: ['Lowercasing, Unicode normalization, whitespace handling, and accent removal change which distinctions survive. They can help consistency or destroy information needed by the task. Modern generative tokenizers often preserve details important for reconstructing code and formatting.', 'A reversible byte-level tokenizer can recover the encoded input exactly, but a preprocessing stage that lowercases cannot recover original capitalization. Decoding tokens is not evidence that the entire preprocessing pipeline was lossless.'] },
      { title: 'Special tokens and target shifting', paragraphs: ['Beginning-of-sequence, end-of-sequence, padding, and chat-role markers have task-specific meanings. Padding fills batch shapes but normally must be excluded from loss and relevant attention. An end marker can teach a generator when to stop.', 'For autoregressive learning, input positions predict the next token. Given [BOS,A,B,EOS], inputs may be [BOS,A,B] and targets [A,B,EOS]. Predicting each input token itself with unrestricted access is a trivial leakage task, not next-token modeling.'], equation: String.raw`\text{inputs}=s_{0:T-1},\qquad\text{targets}=s_{1:T}`, question: 'Why does a tokenizer producing twice as many tokens make long-context attention more expensive?', answer: 'Dense attention has a pairwise T by T interaction matrix. Doubling T approximately quadruples that portion of work and storage, before considering other model operations.' },
    ], application: 'Tokenization affects multilingual fairness, context utilization, cost, exact string handling, and compatibility with pretrained models. Token counts belong to a specific tokenizer, not to text in the abstract.', experiment: 'Compare words, characters, and the toy subword tokenizer on the same sentence. Add punctuation, repeated spaces, an unfamiliar name, and a non-English word. Treat local IDs as demonstration IDs, not GPT vocabulary IDs.', next: 'bpe',
  },
  bpe: {
    prerequisites: ['tokenization'], objectives: ['Perform byte-pair merge training step by step.', 'Separate vocabulary learning from encoding new text.', 'Compare BPE, WordPiece, and unigram tokenization.'],
    sections: [
      { title: 'Compression suggests a vocabulary-learning rule', paragraphs: ['Begin with small symbols, such as characters or bytes. Count adjacent symbol pairs in a training corpus. Merge a frequent pair into a new symbol, update the corpus representation, and repeat until a vocabulary budget or stopping rule is reached.', 'Counts should account for corpus frequencies. A word seen a million times contributes more evidence than a word seen once. Boundary rules determine whether a merge can cross spaces or word boundaries; practical BPE variants differ.'] },
      { title: 'Execute a small merge example', paragraphs: ['Suppose the corpus contains "low" twice and "lower" once, using character symbols inside each word. The pair (l,o) occurs three times and (o,w) also occurs three times. A deterministic tie rule might choose (l,o).', 'After merging, the words become [lo,w], [lo,w], [lo,w,e,r]. Now (lo,w) occurs three times, so the next merge creates "low". This improves compression of a recurring pattern without requiring a dictionary of linguistic morphemes.'], example: 'After these two merges, "lower" is [low,e,r]. Its segmentation is a consequence of corpus counts and merge order, not a declaration that "low" is its only meaningful root.' },
      { title: 'Encoding uses learned merge priorities', paragraphs: ['Training learns the symbol inventory and merge order. Encoding a new word starts from the base symbols and applies eligible learned merges according to their priority. It does not generally recalculate the most frequent pairs from that one user sentence.', 'A byte-level base can represent unfamiliar text without an unknown-character token. Pure character vocabularies may need explicit unknown handling. Decoding concatenates pieces subject to the tokenizer encoding rules. Boundary and whitespace markers must be interpreted correctly.'] },
      { title: 'Other subword objectives make different choices', paragraphs: ['WordPiece is commonly described through likelihood-oriented subword selection and often uses greedy longest-match encoding with continuation markers. Unigram tokenizers start with candidate pieces, prune according to a probabilistic objective, and can choose segmentations by dynamic programming.', 'SentencePiece is a tokenizer framework supporting methods including BPE and unigram; it is not simply another name for one algorithm. Vocabulary size trades output-head cost against sequence length. Bigger vocabularies do not automatically improve every language equally.'], question: 'Should the same rare word receive different IDs because it appears in a different prompt?', answer: 'Not with a fixed deterministic tokenizer. The learned vocabulary and encoding rules are fixed. A toy tokenizer constructing a local vocabulary per input is illustrating mechanics, not pretrained-model compatibility.' },
    ], application: 'Subword vocabularies let language models balance coverage with manageable sequence lengths. Their training corpus and normalization choices can affect downstream performance well before model training.', experiment: 'Run repeated merges on a tiny corpus and write down the pair counts before every step. Then encode a new word using the saved merge order rather than retraining on the new input.', next: 'embeddings',
  },
  embeddings: {
    prerequisites: ['vectors', 'matrices', 'tokenization', 'losses'], objectives: ['Interpret embedding lookup as selecting learned parameters.', 'Compare count-based, predictive, and contextual representations.', 'Explain negative sampling, similarity, and representation limits.'],
    sections: [
      { title: 'Replace arbitrary IDs with learned vectors', paragraphs: ['An embedding table E has V rows, one per vocabulary item, and d columns. Looking up token ID t returns row E[t]. This is equivalent to multiplying a one-hot vector by E, but lookup avoids constructing a huge mostly-zero vector.', 'The table contains V*d parameters. Gradients update rows used by the input lookup, while a tied output classifier may also update rows through vocabulary prediction. An ID is fixed; its associated vector changes during learning.'], equation: String.raw`E\in\mathbb R^{V\times d},\qquad e_t=E[t]` },
      { title: 'Count-based representations provide a baseline', paragraphs: ['A bag-of-words vector counts terms and ignores order. TF-IDF downweights globally frequent terms and emphasizes terms informative within a document. These sparse representations can be strong retrieval and classification baselines.', 'Dense embeddings compress distributional relationships into fewer dimensions. Their geometry is shaped by an objective, not an intrinsic meaning attached to each coordinate. Rotating all vectors and compatible downstream weights can preserve behavior while changing individual coordinates.'] },
      { title: 'Word2Vec learns from neighboring words', paragraphs: ['Skip-gram predicts context words from a center word; CBOW predicts a center from aggregated context. A full vocabulary softmax can be expensive. Negative sampling instead distinguishes observed pairs from sampled noise pairs, using a few negatives per positive.', 'Negative sampling is a contrastive surrogate, not exactly full-softmax maximum likelihood. The noise distribution and number of negatives influence what is learned. Input and output embedding tables have separate roles even when a final application keeps only one.'], equation: String.raw`L=-\log\sigma(u_c^Tv_w)-\sum_{n\in\mathcal N}\log\sigma(-u_n^Tv_w)`, example: 'A positive pair ("cat","sat") should increase its dot-product score under this objective. Sampled unrelated contexts receive pressure toward lower scores. A negative sample is not a claim that the words can never co-occur.' },
      { title: 'GloVe and FastText use different evidence', paragraphs: ['GloVe fits relationships in a global co-occurrence matrix using a weighted objective on log counts. Word2Vec uses local prediction examples. Both exploit distributional evidence, but their exact training objectives differ.', 'FastText composes representations from character n-grams, helping related word forms share information and allowing construction of vectors for some unseen words. Subword composition is useful for morphology but does not eliminate ambiguity or domain mismatch.'] },
      { title: 'Contextual vectors resolve some ambiguity', paragraphs: ['A static embedding gives "bank" the same initial vector in a river sentence and a finance sentence. A contextual network transforms it using surrounding tokens, so later representations can differ by use.', 'Cosine similarity is meaningful only relative to a trained space and task. Embeddings can encode social biases, reflect corpus artifacts, and cluster by style rather than the semantic feature you intended. Analogy examples are demonstrations, not guarantees of symbolic reasoning.'], question: 'Does a coordinate value of 0.8 always mean a token is 80% about a topic?', answer: 'No. Dense coordinates are learned continuous features without a universal interpretation or probability meaning. A downstream model may combine many coordinates to represent a concept.' },
    ], application: 'Embedding lookup begins language modeling; sentence embeddings support retrieval, clustering, and similarity. A retrieval embedding model and a generator may use different objectives and should not be assumed interchangeable.', experiment: 'Normalize two vectors and compare cosine with raw dot product. Explain why the RAG lab uses transparent bag-of-words vectors rather than claiming its tiny local representation is a pretrained semantic embedding model.', next: 'attention',
  },
  attention: {
    prerequisites: ['matrices', 'probability', 'embeddings'], objectives: ['Calculate scores, normalized weights, and weighted values.', 'Explain queries, keys, and values by their computational roles.', 'Derive scaling and masking requirements.'],
    sections: [
      { title: 'Retrieve relevant information instead of one fixed summary', paragraphs: ['A recurrent encoder compresses a sequence into states. Attention lets a requesting representation compare itself with available representations and combine their content. The request is a query, the matching representation is a key, and the content being combined is a value.', 'These are learned vectors, not human-written questions and database records. The analogy explains their roles but does not imply a model stores explicit facts in a clean lookup table. A high attention weight indicates strong routing in this computation, not necessarily a faithful explanation of the final prediction.'] },
      { title: 'First compute compatibility scores', paragraphs: ['For each query, take a dot product with every key. Query and key dimensions must match. Values can have a different feature dimension because they are not multiplied directly by queries.', 'Divide scores by the square root of key dimension. Under simplified independent zero-mean unit-variance coordinates, a dot product of d terms has variance d. Scaling keeps score variance approximately controlled, reducing excessive softmax saturation as dimension grows.'], equation: String.raw`S=QK^T/\sqrt{d_k}` },
      { title: 'Normalize one row at a time', paragraphs: ['Softmax turns each query score row into nonnegative weights summing to one over the allowed keys. Subtract the row maximum before exponentiating for numerical stability.', 'The normalization axis matters. Normalizing down query rows would answer a different question. A mask excludes forbidden keys by assigning negative infinity before softmax. Every query must have at least one valid key to avoid an undefined all-masked row.'], equation: String.raw`A_{ij}=\frac{e^{S_{ij}-m_i}}{\sum_{k\in\text{allowed}(i)}e^{S_{ik}-m_i}}` },
      { title: 'Combine values using the computed weights', paragraphs: ['Multiply the attention matrix by V. Each query receives a weighted sum of value vectors. Before output projection, a single head output lies in the convex hull of its allowed values because the coefficients are nonnegative and sum to one.', 'Scores and values have distinct roles. Changing a value changes content even if attention weights stay fixed. Changing a key can change which content is selected even if its value stays fixed.'], equation: String.raw`O=AV=\operatorname{softmax}(QK^T/\sqrt{d_k}+M)V`, example: 'Query [1,0], keys [1,0] and [0,1], values [2,0] and [0,4]. Scaled scores are [0.7071,0]. Softmax is approximately [0.6698,0.3302]. Output is [1.3396,1.3210]. It is not either original value and not the score vector.' },
      { title: 'Separate architectural attention from causal attention', paragraphs: ['Attention is a general operator. In a decoder, a causal mask allows only current and previous positions. In an encoder, all nonpadding input tokens may be visible. Cross-attention gets queries from one sequence and keys and values from another.', 'For T queries and S keys, dense scores require O(T*S*dk) arithmetic and a T by S attention matrix in a straightforward implementation. Exact memory-efficient kernels reduce materialized intermediates without changing the mathematical operator.'], question: 'If only the first of two keys is allowed, what are the weights and output in the numerical example?', answer: 'The weights become [1,0] and the output is [2,0]. Masking must occur before normalization; zeroing one weight afterward without renormalizing would not produce the same result.' },
    ], application: 'Attention routes information in translation, language generation, vision, multimodal models, and retrieval-like architectures. Its transparency at the operation level does not make model-level reasoning automatically interpretable.', experiment: 'Select one query-key cell in the attention lab and reproduce its scaled score. Predict the effect of causal masking before toggling it. Change query scale and distinguish sharper weights from different value content.', next: 'self-attention',
    implementation: { language: 'JavaScript', explanation: 'A complete one-query attention calculation using the chapter numbers. The maximum subtraction is included for stable softmax.', code: `const query = [1, 0];
const keys = [[1, 0], [0, 1]];
const values = [[2, 0], [0, 4]];
const scores = keys.map(key => key.reduce((sum, value, index) =>
  sum + value * query[index], 0) / Math.sqrt(query.length));
const maximum = Math.max(...scores);
const exponentials = scores.map(score => Math.exp(score - maximum));
const total = exponentials.reduce((sum, value) => sum + value, 0);
const weights = exponentials.map(value => value / total);
const output = values[0].map((_, column) => values.reduce((sum, value, row) =>
  sum + weights[row] * value[column], 0));
console.log({ scores, weights, output });` },
  },
  'self-attention': {
    prerequisites: ['attention'], objectives: ['Derive Q, K, and V from one input sequence.', 'Track every tensor shape.', 'Understand contextualization and permutation equivariance.'],
    sections: [
      { title: 'Each token both asks and supplies information', paragraphs: ['Self-attention derives queries, keys, and values from the same sequence representation X using three learned projections. A token query determines what it seeks; its key determines how others match it; its value is the content it contributes.', 'The three projections need not be identical. They let one representation support different matching and content roles. Input embeddings and projection matrices are both learned, but they are distinct parameter groups.'], equation: String.raw`Q=XW_Q,\quad K=XW_K,\quad V=XW_V` },
      { title: 'Shapes expose the entire computation', paragraphs: ['For T tokens with model width d, X has shape T by d. WQ and WK have shape d by dk; WV has shape d by dv. QK-transpose is T by T; its softmax is T by T; multiplying V gives T by dv.', 'The T by T matrix connects positions, while the projection matrices transform features. Confusing these two axes is a common source of superficially plausible but incorrect code. In batches, preserve batch independence: examples must not attend across the batch axis.'], example: 'For T=4, d=8, dk=2, dv=3, Q and K are 4 by 2, V is 4 by 3, scores are 4 by 4, and output is 4 by 3. The model does not need dk to equal T.' },
      { title: 'The output is a contextual representation', paragraphs: ['The input vector for "bank" can begin identically in two sentences. Different surrounding keys and values lead to different attention outputs, allowing later layers to use context.', 'A layer is not guaranteed to discover linguistic relations such as subject-verb links. Those are learned possibilities under the data and objective. Multiple layers repeatedly transform and mix representations, so an isolated attention map cannot explain the entire model.'] },
      { title: 'Without position signals, order is missing', paragraphs: ['Unmasked self-attention without position-dependent inputs is permutation equivariant: reorder the input tokens and the output reorders correspondingly. It does not intrinsically know which token came first.', 'Position embeddings, rotary transformations, relative biases, or masking can introduce order-dependent structure. A causal mask already treats positions asymmetrically, but practical language models usually add an explicit position mechanism too.'], equation: String.raw`\operatorname{Attention}(PX)=P\operatorname{Attention}(X)\quad\text{without position information or position-dependent masks}`, question: 'Why is adding an embedding for each word alone insufficient to distinguish "dog bites person" from a permutation in unrestricted self-attention?', answer: 'The word identities are present but their ordering is not. Permuting input rows simply permutes corresponding outputs unless a position-dependent mechanism breaks that symmetry.' },
    ], application: 'Self-attention creates contextual token representations in encoders and decoders. It trades a fixed recurrent-state bottleneck for direct token-to-token interactions and their associated cost.', experiment: 'Write the shapes for a six-token, twelve-feature input with key width three. In the lab, compare unmasked and causal rows and explain why the first causal row cannot incorporate later tokens.', next: 'multi-head',
  },
  'multi-head': {
    prerequisites: ['self-attention'], objectives: ['Explain separate attention distributions per head.', 'Track split, concatenate, and output projection shapes.', 'Distinguish multi-head attention from grouped-query variants.'],
    sections: [
      { title: 'One weighted average is a bottleneck', paragraphs: ['A single head forms one attention distribution per query. Several heads can form different distributions in different learned feature subspaces, allowing simultaneous information-routing patterns.', 'Heads are not assigned fixed semantic jobs in advance. One may appear to follow punctuation or syntax, but behavior can overlap, vary by context, or change after pruning. The mathematical advantage is multiple independently normalized mixtures.'] },
      { title: 'Compute heads separately, then mix their outputs', paragraphs: ['Each head projects queries, keys, and values, computes its own scaled scores, normalizes, and combines values. Concatenate head outputs along the feature axis, not the token axis. A learned output matrix mixes the concatenated features back into model width.', 'With h heads and per-head width d/h, concatenation returns width d. Implementations often use one fused QKV projection then reshape into heads. That is an efficient organization of the same operations, not a fundamentally different architecture.'], equation: String.raw`\operatorname{MHA}(X)=\operatorname{Concat}(H_1,\ldots,H_h)W_O`, example: 'For model width 12 and 3 heads, each head may use width 4. A sequence of 5 tokens gives each head a 5 by 5 attention matrix and a 5 by 4 output. Concatenation yields 5 by 12; WO is 12 by 12.' },
      { title: 'More heads do not necessarily mean more total parameters', paragraphs: ['At fixed model width with evenly divided heads, the combined projection dimensions remain roughly unchanged. Standard Q, K, V, and output matrices contribute approximately 4d squared weights, ignoring biases.', 'The attention score storage contains h*T*T values in a naive implementation. Increasing head count at fixed d reduces per-head width but can affect kernel efficiency, memory, and representational behavior. Head count is not a monotonic quality knob.'] },
      { title: 'Share keys and values to reduce decode memory', paragraphs: ['Multi-query attention shares one key and value head across several query heads. Grouped-query attention shares them within groups. Queries remain distinct, so each query head can still form its own distribution over shared keys.', 'This reduces KV-cache size during autoregressive decoding. It changes the architecture and capacity, unlike an exact kernel optimization such as FlashAttention. Conversion and retraining choices determine quality trade-offs.'], question: 'If eight query heads use two KV heads, does the cache store eight separate key copies?', answer: 'No. It stores the two KV groups and maps query heads to their group. This is the main memory-saving purpose of grouped-query attention.' },
    ], application: 'Multi-head attention supports diverse contextual interactions. Grouped-query variants are especially important for serving long contexts and many simultaneous users.', experiment: 'Construct two manual heads: one weights two values [1,0], another [0,1]. Concatenate their outputs and apply a chosen output matrix. Notice that averaging the heads would discard information the concatenation preserves.', next: 'positions',
  },
  transformer: {
    prerequisites: ['multi-head', 'residuals', 'normalization', 'positions'], objectives: ['Trace a complete transformer block.', 'Distinguish encoder, decoder, and encoder-decoder architectures.', 'Explain token mixing, channel mixing, and parameter costs.'],
    sections: [
      { title: 'A transformer alternates two kinds of computation', paragraphs: ['Attention mixes information across token positions. A position-wise feed-forward network transforms features within each token. Residual connections preserve a route for existing information, and normalization stabilizes the scales presented to learned sublayers.', 'The feed-forward weights are shared across positions, but each token has different activations. Attention and the MLP play complementary roles: removing either changes the model family and its capacity.'] },
      { title: 'Specify pre-norm or post-norm explicitly', paragraphs: ['A common pre-norm block first normalizes the input, applies attention, and adds the result to the residual. It then normalizes again, applies the MLP, and adds again. The residual stream bypasses the normalization inside each branch.', 'The original post-norm arrangement normalizes after each addition. Both are transformers, but they have different gradient paths and optimization behavior. A numerical trace must state which it implements rather than silently mixing formulas.'], equation: String.raw`U=X+\operatorname{MHA}(\operatorname{LN}(X)),\quad Y=U+\operatorname{MLP}(\operatorname{LN}(U))` },
      { title: 'The MLP expands then contracts features', paragraphs: ['A standard MLP projects d model features to dff hidden features, applies GELU or another nonlinearity, then projects back to d. Often dff is a multiple of d. Its two main weight matrices contain approximately 2*d*dff parameters.', 'Gated variants such as SwiGLU multiply an activated branch by another learned branch before the output projection. Their expansion ratios may be adjusted to maintain a comparable parameter budget. They are not simply a scalar activation replacement with identical parameter count.'], equation: String.raw`\operatorname{FFN}(x)=\phi(xW_1+b_1)W_2+b_2`, example: 'With d=64 and dff=256, the two FFN matrices contain 32,768 weights. Standard attention projections contain about 4*64*64=16,384. The FFN can hold more parameters than attention.' },
      { title: 'Three families differ in visibility and objective', paragraphs: ['An encoder uses bidirectional input attention and suits representation tasks such as classification or masked-token prediction. A decoder-only model uses causal self-attention and predicts the next token. An encoder-decoder model encodes a source and uses a causal decoder with cross-attention to the source.', 'Cross-attention queries come from decoder states while keys and values come from encoder outputs. The decoder can see the full source but not future target tokens. "Decoder" describes this architecture convention, not merely any function that converts numbers back to text.'] },
      { title: 'Parallel training, sequential generation', paragraphs: ['During teacher-forced training, all target-prefix positions are known, so a masked transformer processes their predictions in parallel. Causal masking prevents each position from seeing its future target despite this parallel computation.', 'During generation, the next input token is unknown until sampled or selected from the current output distribution. Steps remain autoregressive. KV caching avoids recomputing previous key and value projections, but does not remove this dependency.'], question: 'Does parallel processing during training violate causality?', answer: 'No, if attention masks and shifted targets are correct. All positions can be computed together while each prediction depends only on its allowed prefix.' },
    ], application: 'Transformers support language, images, audio, and multimodal learning because their representation mixing is flexible. The token trace is a tiny post-norm example, while many current decoder models use pre-norm and other modifications.', experiment: 'Trace one token through embedding, projections, attention, residual, normalization, MLP, and logits. Label every state with its shape. Identify which steps mix tokens and which only transform one token features.', next: 'gpt',
  },
  positions: {
    prerequisites: ['vectors', 'self-attention'], objectives: ['Explain why order information is needed.', 'Compare learned, sinusoidal, rotary, and relative mechanisms.', 'Distinguish context-length support from reliable long-context use.'],
    sections: [
      { title: 'Order must enter through a mechanism', paragraphs: ['Without position information or position-dependent masking, self-attention treats token rows symmetrically. Language requires order: a subject before a verb is not interchangeable with an arbitrary permutation.', 'Position can enter as added input vectors, transformations of queries and keys, or biases on pairwise scores. These choices affect what is extrapolated when a sequence becomes longer than the training examples.'] },
      { title: 'Absolute learned and sinusoidal embeddings', paragraphs: ['Learned absolute positions use a trainable table indexed by position and add the chosen row to a token embedding. It is simple but positions outside the table have no trained entries.', 'Sinusoidal embeddings assign pairs of sine and cosine values at different frequencies. They can be evaluated at arbitrary positions without a learned lookup table. This algebraic ability does not guarantee that a model trained on short sequences will reason well on much longer ones.'], equation: String.raw`PE(p,2i)=\sin\left(p/10000^{2i/d}\right),\quad PE(p,2i+1)=\cos\left(p/10000^{2i/d}\right)` },
      { title: 'Rotary position embeddings rotate coordinate pairs', paragraphs: ['RoPE applies position-dependent rotations to query and key coordinate pairs. Dot products between rotated vectors then depend on relative position differences through rotation identities.', 'A rotation preserves each pair norm, changing orientation rather than arbitrarily increasing magnitude. Typical RoPE applies to queries and keys, not directly to values. Frequency schedules and long-context scaling variants differ across models.'], equation: String.raw`R(\theta)\begin{bmatrix}a\\b\end{bmatrix}=\begin{bmatrix}a\cos\theta-b\sin\theta\\a\sin\theta+b\cos\theta\end{bmatrix}`, example: 'Rotate [1,0] by 90 degrees to get [0,1]. Its norm remains one. If both query and key rotate by the same angle, their dot product is unchanged; differing position angles create relative effects.' },
      { title: 'Relative biases change attention scores directly', paragraphs: ['Relative-position schemes add a learned or prescribed bias based on distance or distance buckets. ALiBi uses head-specific linear distance penalties in attention scores, usually favoring nearer positions.', 'Context limits involve positional mechanisms, training data, memory, and evaluation. A model accepting 100,000 tokens may fail to retrieve a detail in the middle or combine distant evidence reliably. Test retrieval and reasoning as a function of position, not just whether the input fits.'], question: 'Does a position formula defined for every integer automatically confer unlimited usable context?', answer: 'No. The model still faces distribution shift, finite training experience, compute costs, and possible failures to use distant information.' },
    ], application: 'Position mechanisms connect attention to ordered sequences. They also matter for extending pretrained contexts without misleading users about effective long-context quality.', experiment: 'Calculate a 2D rotation for two query positions and compare their key dot products. Separate an absolute coordinate value from the relative angle that affects similarity.', next: 'normalization',
  },
  normalization: {
    prerequisites: ['probability', 'mlp'], objectives: ['Calculate LayerNorm by hand.', 'Distinguish normalization axes and training behavior.', 'Explain RMSNorm and the role of learned scale.'],
    sections: [
      { title: 'Control internal scale, not the meaning of a feature', paragraphs: ['Deep computations can present each layer with widely changing input scales. Normalization rescales groups of activations using their statistics. This can improve conditioning and stability but does not guarantee that representations become Gaussian or semantically interpretable.', 'Data standardization is usually fitted before training on dataset features. Internal normalization is part of the model forward computation, often with learnable scale and offset. These are related operations with different roles.'] },
      { title: 'LayerNorm normalizes one token across features', paragraphs: ['For a token vector of d features, compute its feature mean and population variance using denominator d. Subtract the mean and divide by the square root of variance plus epsilon. Apply learned per-feature gamma and beta.', 'Each token computes its own statistics, independently of other examples in the batch. Gamma and beta can restore useful scales and shifts after standardization. Epsilon avoids division by zero for constant vectors.'], equation: String.raw`\mu=\frac1d\sum_ix_i,\quad v=\frac1d\sum_i(x_i-\mu)^2,\quad y_i=\gamma_i\frac{x_i-\mu}{\sqrt{v+\epsilon}}+\beta_i`, example: 'For [1,3], mean=2 and variance=1. Ignoring a tiny epsilon, normalized values are [-1,1]. With gamma=[2,0.5], beta=[0.1,-0.2], output becomes [-1.9,0.3].' },
      { title: 'BatchNorm uses different groups and running statistics', paragraphs: ['BatchNorm commonly normalizes each channel using statistics across batch and, for images, spatial dimensions. During training it uses current batch statistics and updates running estimates. During evaluation it usually uses the stored estimates.', 'Small or nonrepresentative batches can make those estimates noisy. LayerNorm uses within-example feature statistics and generally behaves the same in training and evaluation apart from surrounding layers. Setting a model to evaluation mode matters even when gradient calculation is disabled.'] },
      { title: 'RMSNorm omits mean subtraction', paragraphs: ['RMSNorm divides by root mean square and applies learned scale, typically without subtracting a mean. It is common in decoder models and can be cheaper than full LayerNorm.', 'LayerNorm is approximately invariant to a shared additive offset before its affine transform; RMSNorm is not because it does not center. Both use epsilon and learned parameters, so exact scale invariance claims require care.'], equation: String.raw`\operatorname{RMSNorm}(x)_i=\gamma_i\frac{x_i}{\sqrt{\frac1d\sum_jx_j^2+\epsilon}}`, example: 'For [1,3], RMS is sqrt(5), giving approximately [0.4472,1.3416] before learned scaling. This differs from LayerNorm [-1,1].' },
      { title: 'Placement affects the residual path', paragraphs: ['Pre-norm normalizes input to a residual branch; post-norm normalizes the sum after the branch. A final normalization is often used at the end of a pre-norm stack.', 'Do not accidentally normalize across token positions when intending LayerNorm across features. That would make a token depend on other positions through statistics, potentially violating causal assumptions and changing the algorithm.'], question: 'Can setting batch size to one reproduce LayerNorm by using BatchNorm?', answer: 'Not in general. The reduction axes, affine parameters, and running-statistic behavior differ. Batch size alone does not make the operations equivalent.' },
    ], application: 'Normalization details are essential when reproducing a transformer or transferring checkpoint weights. The same shapes with different axes or epsilon placement can yield different predictions.', experiment: 'Calculate LayerNorm and RMSNorm for [1,3] and for [11,13]. Compare which changes after adding a shared constant. Revisit the transformer block now that its normalization is explicit.', next: 'transformer',
  },
  gpt: {
    prerequisites: ['transformer', 'positions', 'normalization', 'losses'], objectives: ['Connect token prediction to the full decoder architecture.', 'Derive shifted-target training and generation.', 'Build a small model in verifiable stages without confusing a toy with a pretrained LLM.'],
    sections: [
      { title: 'A language model assigns sequence probability', paragraphs: ['The probability chain rule factors a sequence into conditional next-token probabilities. A causal language model parameterizes each conditional using only the prefix. Training minimizes negative log probability of actual next tokens.', 'A decoder-only transformer is one way to compute these conditionals. Its output is a vocabulary distribution, not a sentence or a guaranteed fact. Generation repeatedly selects a token from that distribution and extends the prefix.'], equation: String.raw`P(s_1,\ldots,s_T)=\prod_{t=1}^TP(s_t\mid s_{<t}),\qquad L=-\frac1T\sum_t\log P_\theta(s_t\mid s_{<t})` },
      { title: 'Trace the complete architecture and shapes', paragraphs: ['Start with integer IDs of shape B by T. Embedding lookup gives B by T by d. Add or apply the chosen position mechanism, pass through L causal transformer blocks, and apply final normalization when the architecture calls for it.', 'A vocabulary projection maps each d-dimensional state to V logits, producing B by T by V. Some models tie this output matrix to the input embedding table transpose. That shares parameters but does not mean input and output operations are identical.'], example: 'B=2, T=16, d=32, V=100: hidden activations are 2 by 16 by 32; logits are 2 by 16 by 100. The embedding table has 3,200 weights. A tied output projection reuses them instead of adding another 3,200.' },
      { title: 'Train every position without revealing its answer', paragraphs: ['For a token stream [a,b,c,d], use inputs [a,b,c] and targets [b,c,d]. Position zero predicts b from a; position one predicts c from [a,b]. A causal mask ensures position zero cannot read input b even though that token is present elsewhere in the batch tensor.', 'Flatten batch and time dimensions only when passing logits and labels to an appropriate cross-entropy loss, preserving the vocabulary axis. Mask padding and document-boundary transitions according to the data construction. Keep validation documents separate from training rather than randomly splitting near-identical windows.'] },
      { title: 'A build project with concrete milestones', paragraphs: ['Milestone 1: choose a small licensed text corpus, split it by document, and build a fixed character vocabulary. Train a bigram transition baseline. It learns only P(next|current), so it is not yet a transformer. Record validation negative log likelihood as a reference.', 'Milestone 2: implement token and position embeddings plus one masked attention head. Check causality by changing future tokens and confirming earlier logits stay unchanged. Milestone 3: add multi-head output projection, two residual branches, normalization, and an MLP. Verify every shape before training.', 'Milestone 4: use automatic differentiation and AdamW to fit a tiny batch, then train on shuffled context windows with held-out validation. Milestone 5: implement autoregressive sampling, EOS handling, and a context-window policy. Milestone 6: add KV caching and compare cached versus uncached logits within numerical tolerance. Each milestone should preserve a working smaller model.'] },
      { title: 'Estimate the budget before running', paragraphs: ['For a conventional block with dff=4d, attention weights total about 4d squared and MLP weights about 8d squared. L layers therefore contribute roughly 12L*d squared weights, plus embeddings, normalization, biases, and any untied output head.', 'A two-layer width-64 character model with V=100 has roughly 98,304 block weights plus 6,400 embedding weights. This is useful for learning code paths, not for producing reliable assistant behavior. Training data, scale, and post-training distinguish a modern deployed LLM from a small architecture demonstration.'], equation: String.raw`N\approx12Ld^2+Vd\quad\text{for a tied, conventional decoder approximation}`, question: 'Can a model cheat if targets are shifted correctly but its attention is unmasked?', answer: 'Yes. At position t it can see input token t+1, which is precisely its target. Correct target shifting and correct causal visibility are both required.' },
      { title: 'Debug using falsifiable invariants', paragraphs: ['A random uniform predictor should have cross entropy approximately log(V). Overfit a tiny batch to verify the training path. Perturb future tokens to verify causality. Compare one full-prefix forward pass with incremental cached decoding. Inspect token IDs after decoding to catch tokenizer mismatches.', 'A fluent sample is not a sufficient check: accidental leakage or memorization can produce convincing text. Keep numerical baselines, explicit masks, and held-out loss even in a small educational project. The browser token trace demonstrates forward computation, not training of a production GPT.'] },
    ], application: 'GPT-style models turn a reusable next-token objective into broad generative capability at scale. The objective alone does not provide factuality, tool permissions, or alignment with user intent.', experiment: 'Run the miniature GPT implementation in the Code lab. Trace its Value operations before changing width, head count, or training steps. Build the bigram baseline as the first milestone, then add a held-out document split to the transformer. Compare validation loss, not just the appearance of one sample.', next: 'sampling',
    implementation: { language: 'JavaScript', explanation: 'A complete, dependency-free miniature decoder: scalar reverse-mode autodiff, learned character and position embeddings, two causal attention heads, pre-norm residual blocks, a ReLU MLP, tied output embeddings, cross entropy, clipping, and Adam. Value stores a number, its gradient, its parents, and a local backward function. The forward function excludes future keys rather than materializing negative-infinity masks. Twelve updates keep the browser run short; the sample is deliberately undertrained, and reported loss is training loss, not held-out quality. To study learning, increase the training budget gradually outside the timed browser worker. Cropping to the last eight tokens resets learned positions; this is a stated short-window generation policy, not KV caching. The code begins with a causality check: changing a future token must leave the first position logits unchanged.', code: tinyGptCode },
  },
  sampling: {
    prerequisites: ['gpt', 'probability'], objectives: ['Calculate temperature and filtering effects.', 'Distinguish greedy decoding, sampling, and beam search.', 'Explain reproducibility, stopping, and repetition controls.'],
    sections: [
      { title: 'A distribution still needs a selection rule', paragraphs: ['The model outputs logits. A decoding strategy decides which token to emit. Greedy decoding selects the maximum-probability token, while sampling draws according to a probability distribution.', 'Greedy choices maximize each local conditional, not necessarily the probability of the completed sequence. Sampling adds diversity but can select low-quality continuations. Neither strategy guarantees factual correctness.'] },
      { title: 'Temperature rescales relative preferences', paragraphs: ['Divide logits by positive temperature before softmax. Temperatures below one sharpen differences; above one flatten them. Adding a common constant to logits has no effect, but multiplying by an inverse temperature does.', 'The zero-temperature limit corresponds to selecting maxima, but implementing literal division by zero is invalid. With tied maxima, a tie-breaking policy still matters. Temperature changes the output distribution without changing learned weights.'], equation: String.raw`p_i(\tau)=\frac{e^{z_i/\tau}}{\sum_je^{z_j/\tau}},\quad\tau>0`, example: 'For logits [2,1,0], temperature 1 gives about [0.665,0.245,0.090]. Temperature 0.5 gives about [0.867,0.117,0.016]. The ranking stays the same while confidence changes.' },
      { title: 'Top-k and nucleus filtering change support', paragraphs: ['Top-k keeps the k highest-scoring tokens, sets other probabilities to zero, and renormalizes. Nucleus or top-p sampling keeps the smallest sorted prefix whose cumulative probability reaches a threshold p, then renormalizes.', 'Top-k uses a fixed candidate count; top-p adapts to distribution sharpness. A high-probability token may be alone in a sharp nucleus, while many tokens may survive a flat distribution. The order of temperature and filtering can affect the result.'], example: 'With probabilities [0.6,0.25,0.1,0.05], top-p=0.8 keeps the first two because their cumulative mass is 0.85. Renormalized probabilities are about [0.706,0.294].' },
      { title: 'Beam search tracks partial alternatives', paragraphs: ['Beam search retains several promising prefixes scored by accumulated log probability. Length penalties may be used because multiplying probabilities tends to favor short sequences. It approximates structured search, not independent top-k sampling.', 'Beam search can suit constrained outputs or some translation settings but may produce repetitive generic open-ended text. Repetition penalties and no-repeat rules alter the objective and can interfere with legitimate repeated code or names.'] },
      { title: 'Generation needs explicit operational limits', paragraphs: ['Stop on an end token, a specified stop sequence, or a maximum new-token budget. Distinguish total context length from new tokens. When truncating context, preserve the required formatting and be honest about lost information.', 'A fixed random seed improves reproducibility under a fixed implementation, but GPU nondeterminism and changed batching can still matter. Record tokenizer, model revision, prompt template, and decoding settings when comparing outputs.'], question: 'Does top-p=0.9 mean every generated statement is 90% likely to be true?', answer: 'No. It is a threshold on cumulative next-token probability mass, not a calibrated claim about truth or whole-response quality.' },
    ], application: 'Decoding settings change diversity, consistency, latency, and output format. Use task-level evaluation instead of describing one temperature as inherently more intelligent.', experiment: 'Use the fixed-logit generation lab to isolate sampling from model learning. Compare distributions before generating samples. Its verbs are a controlled distribution, not completions from a pretrained language model.', next: 'pretraining',
  },
  pretraining: {
    prerequisites: ['gpt', 'training'], objectives: ['Separate pretraining, continued pretraining, and fine-tuning.', 'Explain dataset quality, packing, and objective construction.', 'Understand instruction tuning and parameter-efficient adaptation.'],
    sections: [
      { title: 'Pretraining builds a broadly useful predictive model', paragraphs: ['Pretraining optimizes an objective on a large corpus before specializing the model to a downstream task. Decoder models commonly predict next tokens; encoder models may reconstruct masked tokens. The objective determines which information is useful to learn.', 'Data selection, licensing, deduplication, filtering, mixture weights, and sensitive-information handling are core model choices. More raw bytes do not necessarily mean more useful independent evidence. Repeated benchmarks in the training corpus can invalidate evaluation.'] },
      { title: 'Construct examples without accidental shortcuts', paragraphs: ['Tokenize using a fixed tokenizer, organize documents, and form bounded-length sequences. Packing several documents improves utilization, but decide whether attention may cross document boundaries and where EOS tokens appear.', 'Training loss should average over valid target tokens. Record the effective token budget rather than only epochs when corpora and packing vary. Hold out documents and representative domains to detect overfitting and distribution-specific regressions.'] },
      { title: 'Fine-tuning changes the training distribution and objective emphasis', paragraphs: ['Continued pretraining usually extends language-model training on additional domain text. Supervised fine-tuning uses example inputs and desired outputs, often in a chat template. A common setup masks loss on prompt tokens and trains on assistant responses.', 'Instruction tuning teaches response behavior from demonstrations but does not guarantee reasoning correctness or alignment in unseen situations. Aggressive fine-tuning can overwrite useful general capabilities, so evaluate both target-domain gains and broader regressions.'] },
      { title: 'Adapt fewer parameters with low-rank updates', paragraphs: ['LoRA freezes a base matrix W and learns a low-rank update BA, with rank r much smaller than input and output widths. The update can be scaled and optionally merged into W for inference when the deployment representation permits it.', 'For a d-by-k matrix, full tuning updates d*k values; the low-rank factors use r*(d+k). This reduces trainable parameters and optimizer state, not necessarily all activation memory or the need to load the base model.'], equation: String.raw`W'=W+\frac\alpha r BA,\quad B\in\mathbb R^{d\times r},\quad A\in\mathbb R^{r\times k}`, example: 'A 1024 by 1024 matrix has 1,048,576 entries. Rank-8 factors have 8*(1024+1024)=16,384 trainable entries, about 1.56% of that matrix size.' },
      { title: 'Evaluate before calling adaptation successful', paragraphs: ['Measure held-out loss and task metrics, examine formatting and refusal behavior where relevant, and compare against the unchanged base model. Include adversarial or shifted inputs only where they reflect the intended deployment.', 'The XOR training lab demonstrates general optimization mechanics, not LLM pretraining scale. A real fine-tuning recipe also needs compatible model weights, tokenizer, data permissions, hardware estimates, checkpointing, and evaluation.'], question: 'Does a small LoRA adapter mean the whole model can run in only the adapter memory?', answer: 'No. The frozen base weights are still required unless a separate compatible system provides them. Training may also need substantial activation memory.' },
    ], application: 'Pretraining provides broad representations; adaptation changes domain competence or interaction behavior. Good dataset construction and evaluation are often more decisive than a minor optimizer change.', experiment: 'Take a chat example and mark precisely which tokens receive loss under assistant-only tuning. Estimate full versus rank-8 adaptation parameter counts for a chosen projection.', next: 'compression',
  },
  compression: {
    prerequisites: ['pretraining', 'probability'], objectives: ['Explain quantization scales and approximation error.', 'Distinguish pruning, distillation, and low-rank adaptation.', 'Measure quality and hardware-dependent speed together.'],
    sections: [
      { title: 'Compression changes a resource-quality trade-off', paragraphs: ['A model consumes memory for weights, activations, caches, gradients, and optimizer state depending on the workload. Compressing one category does not eliminate the others. An inference-only optimization can differ substantially from a training optimization.', 'Define the objective: lower storage, lower latency, higher throughput, or fitting on a device. Fewer nominal bits or nonzero weights do not automatically produce faster kernels.'] },
      { title: 'Quantization maps continuous values to a finite grid', paragraphs: ['An affine quantizer uses a scale and zero point to map a real value to a bounded integer, then approximates it by dequantization. Symmetric variants use a zero-centered range; per-channel or group-wise scales adapt to different weight distributions.', 'Outliers can stretch a shared scale and waste resolution on most values. Calibration data, clipping thresholds, and quantization-aware training can improve the trade-off. Weight-only quantization differs from quantizing activations and KV caches.'], equation: String.raw`q=\operatorname{clip}(\operatorname{round}(x/s)+z,q_{min},q_{max}),\quad\hat x=s(q-z)`, example: 'With scale 0.1 and zero point 0, x=0.26 maps to q=3 and reconstructs as 0.3, error 0.04. Clipping outside the integer range can introduce much larger error.' },
      { title: 'Pruning removes structure or individual weights', paragraphs: ['Unstructured pruning zeros selected weights, often guided by magnitude or more sophisticated importance measures. Dense hardware may still perform the same work unless sparse storage and kernels exploit the pattern.', 'Structured pruning removes whole channels, heads, or blocks, creating smaller dense operations but possibly removing more useful capacity. Fine-tuning after pruning may recover quality. A small weight is not universally unimportant because downstream scaling and interactions matter.'] },
      { title: 'Distillation learns a smaller function from a larger teacher', paragraphs: ['A student can imitate teacher probabilities or intermediate representations in addition to learning ground-truth labels. Soft targets expose relative preferences among non-target classes, providing richer information than a hard label.', 'Temperature-softened KL objectives are common; multiplying by temperature squared is a convention used to compensate gradient scaling in certain formulations. Distillation transfers teacher behavior, including mistakes and biases, rather than guaranteeing the student surpasses the teacher.'], equation: String.raw`L=(1-\lambda)L_{label}+\lambda\tau^2D_{KL}(p_{teacher}^{(\tau)}\|p_{student}^{(\tau)})` },
      { title: 'Measure the deployed artifact', paragraphs: ['Evaluate accuracy, calibration, rare cases, output stability, latency percentiles, memory, and throughput on the actual hardware and batch shapes. Include scale metadata and packing overhead in memory estimates.', 'Low-rank adaptation is primarily a training specialization method, not automatically inference compression. A merged LoRA update leaves the base matrix dimensions unchanged. Quantization and distillation address different resource constraints and can sometimes be combined.'], question: 'Do four-bit weights guarantee four times faster inference than sixteen-bit weights?', answer: 'No. Speed depends on memory bottlenecks, dequantization, kernel support, shapes, and other computations. Four times smaller raw weight storage is not four times lower end-to-end latency.' },
    ], application: 'Compression makes deployment possible on constrained devices and improves serving economics. The right comparison is quality at a measured resource budget, not just a bit-width label.', experiment: 'Quantize [0.04,0.26,-0.18,1.7] using two scales and a small signed integer range. Compute reconstruction error and identify clipping. Compare theoretical weight memory with total serving memory.', next: 'diffusion',
  },
}